out = []
for l in P["lines"]:
    n = l["line"]
    g, sw, obj, vc, how, bg, gr, mo, ti, to, inter, acc, age, assets, notes = L[n]
    seq = next(k for k, (_, ls) in SEQ.items() if n in ls)
    wd = next((w for w in l["words"] if w["word"] == sw), None)
    assert wd, f"syncWord {sw} not in line {n}"
    out.append({
        "line": n, "sequence": seq, "sequenceTitle": SEQ[seq][0],
        "start": l["start"], "end": l["end"], "text": l["text"],
        "teachingGoal": g, "syncWord": sw, "syncWordStart": wd["start"],
        "onScreenObject": obj, "visualConcept": vc, "howShownVisually": how,
        "onScreenText": "none", "background": bg, "graphics": gr, "motion": mo,
        "transitionIn": ti, "transitionOut": to, "interaction": inter,
        "energy": AM[n]["energy"] if n not in (27, 32) else (5 if n == 27 else 8),
        "accuracyNotes": acc, "ageCheck": age or "OK for 6–9: shown, not read.",
        "customAssetsNeeded": assets, "notes": notes,
        "setup": SHOTS[n][0], "backdrop": SHOTS[n][1], "shot": SHOTS[n][2], "transitionIn": SHOTS[n][3], "views": SHOTS[n][4], "extras": SHOTS[n][5],
    })
    if n in CHANGED_HOW:
        out[-1]["howShownVisually"] = CHANGED_HOW[n]
(ROOT / "visual-screenplay.json").write_text(json.dumps({"sequences": {k: {"title": t, "lines": ls} for k, (t, ls) in SEQ.items()}, "lines": out}, ensure_ascii=False, indent=2))
print(len(out), "lines;", "onScreenText != none:", sum(o["onScreenText"] != "none" for o in out))
